	public static class ValueDomainOption
{	public static readonly ValueDomainOption VALUE_CONSTPROP = new();
	public static readonly ValueDomainOption VALUE_INTERVAL = new();
	public static readonly ValueDomainOption VALUE_INTERVAL_LX86 = new();
	public static readonly ValueDomainOption VALUE_POWERSET = new();
	public static readonly ValueDomainOption VALUE_PARITY = new();
	public static readonly ValueDomainOption VALUE_PENTAGON = new();
	public static readonly ValueDomainOption VALUE_PENTAGON_LX86 = new();
	public static readonly ValueDomainOption VALUE_SIGN = new();
	public static readonly ValueDomainOption VALUE_UPPERBOUND = new();
	public static readonly ValueDomainOption DDATA_AVAILABLE = new();
	public static readonly ValueDomainOption DDATA_CONSTPROP = new();
	public static readonly ValueDomainOption PDATA_REACHING = new();
	public static readonly ValueDomainOption PDATA_LIVENESS = new();
	public static readonly ValueDomainOption VALUE_TAINT = new();
	public static readonly ValueDomainOption VALUE_TAINT3L = new();
	public static readonly ValueDomainOption NONINTERFERENCE = new();
	public static readonly ValueDomainOption STABILITY = new();
	public static readonly ValueDomainOption DEFAULT = new();


		private string optionString;

		private ValueDomainOption(string optString) {
			this.optionString = optString;
		}

		/* @Override */
		public string toString() {
			return optionString;
		}

		/* @SuppressWarnings({ "rawtypes", "unchecked" }) */
		public ValueDomain getDomain(Program program) {
			suppress = DEFAULT_LISA_TOP_REPRESENTATION;
			if (this == VALUE_INTERVAL ||
				this == VALUE_INTERVAL_LX86 ||
				this == VALUE_PENTAGON ||
				this == VALUE_PENTAGON_LX86 ||
				this == VALUE_POWERSET) {
				suppress = "[-Inf, +Inf]";
			}
			if (this == VALUE_UPPERBOUND) {
				suppress = "{}";
			}
			if (this == STABILITY) {
				suppress = "=";
			}
			if (this == NONINTERFERENCE) {
				suppress = "HL";
			}
			if (this == VALUE_TAINT || this == VALUE_TAINT3L) {
				suppress = "_";
			}
			switch (this) {
				case VALUE_CONSTPROP => new(
					new PcodeByteBasedConstantPropagation(program.getLanguage()));
				case VALUE_INTERVAL: return new(new PcodeInterval());
				case VALUE_INTERVAL_LX86: return new(new PcodeIntervalLowX86());
				case VALUE_PARITY: return new(new PcodeParity());
				case VALUE_PENTAGON: return new PcodePentagon();
				case VALUE_PENTAGON_LX86: return new PcodePentagonLowX86();
				case VALUE_POWERSET => new(
					new PcodeNonRedundantPowersetOfInterval());
				case VALUE_SIGN: return new(new PcodeSign());
				case VALUE_TAINT: return new(new PcodeTaint(false));
				case VALUE_TAINT3L: return new(new PcodeThreeLevelTaint());
				//case VALUE_TREND -> new ValueEnvironment<>(Trend.TOP);
				case VALUE_UPPERBOUND: return new(new PcodeUpperBounds());
				case DDATA_AVAILABLE: return new(new AvailableExpressions());
				case DDATA_CONSTPROP => new(
					new PcodeDataflowConstantPropagation(program.getLanguage()));
				case PDATA_REACHING: return new(new ReachingDefinitions());
				case PDATA_LIVENESS: return new(new Liveness());
				case NONINTERFERENCE: return new(new NonInterference());
				case STABILITY => new PcodeStability(
					new(new PcodeInterval()).top());
				default: new(new PcodeInterval());
			};
		}
	}

