		/* @Override */
		public string toString() {
			return optionString;
		}

		/* @SuppressWarnings("rawtypes") */
		public InterproceduralAnalysis<object> getAnalysis() {
			switch (this) {
				case CONTEXT: return new();
				case FULLSTACK: return new(FullStackToken.getSingleton());
				case KDEPTH: return new(KDepthToken.getSingleton(threshhold));
				case LASTCALL: return new(LastCallToken.getSingleton());
